"""Articles API with HTTP-level caching (Cache-Control + Last-Modified/If-Modified-Since)."""
import os
import sqlite3
from datetime import datetime, timezone
from email.utils import formatdate, parsedate_to_datetime

from flask import Flask, g, jsonify, request

DB_PATH = os.environ.get("ARTICLE_DB", "articles.db")

_SCHEMA = """
CREATE TABLE IF NOT EXISTS articles (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    body TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
"""


def utcnow() -> datetime:
    return datetime.now(timezone.utc).replace(tzinfo=None)


def http_date(dt: datetime) -> str:
    """Format a naive-UTC datetime as an RFC 1123 HTTP-date."""
    return formatdate(dt.replace(tzinfo=timezone.utc).timestamp(), usegmt=True)


def parse_http_date(value: str):
    try:
        return parsedate_to_datetime(value).astimezone(timezone.utc).replace(tzinfo=None)
    except (TypeError, ValueError):
        return None


def get_db() -> sqlite3.Connection:
    if "db" not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db


def create_app(db_path: str | None = None) -> Flask:
    app = Flask(__name__)
    app.config["DB_PATH"] = db_path or DB_PATH
    with sqlite3.connect(app.config["DB_PATH"]) as db:
        db.executescript(_SCHEMA)
    return app


app = None  # created lazily so tests can pass their own db path


def _db():
    if "db" not in g:
        g.db = sqlite3.connect(current_app_db())
        g.db.row_factory = sqlite3.Row
    return g.db


def current_app_db() -> str:
    return current_app().config["DB_PATH"]


from flask import current_app  # noqa: E402  (kept local to avoid confusion)


def row_to_dict(row) -> dict:
    return {
        "id": row["id"],
        "title": row["title"],
        "body": row["body"],
        "updated_at": row["updated_at"],
    }


def register_routes(app: Flask) -> None:
    @app.get("/articles/<int:article_id>")
    def get_article(article_id: int):
        row = _db().execute(
            "SELECT * FROM articles WHERE id = ?", (article_id,)
        ).fetchone()
        if row is None:
            return jsonify(error="article not found"), 404

        updated_at = datetime.fromisoformat(row["updated_at"])
        headers = {
            "Cache-Control": "public, max-age=60",
            "Last-Modified": http_date(updated_at),
        }

        ims_raw = request.headers.get("If-Modified-Since")
        if ims_raw:
            ims = parse_http_date(ims_raw)
            # Second-granularity comparison, per RFC 9110 (HTTP-dates have no sub-seconds).
            if ims is not None and ims >= updated_at.replace(microsecond=0):
                return "", 304, headers

        return jsonify(row_to_dict(row)), 200, headers

    @app.put("/articles/<int:article_id>")
    def put_article(article_id: int):
        payload = request.get_json(silent=True) or {}
        title = payload.get("title")
        body = payload.get("body")
        if title is None and body is None:
            return jsonify(error="provide 'title' and/or 'body'"), 400

        db = _db()
        row = db.execute(
            "SELECT * FROM articles WHERE id = ?", (article_id,)
        ).fetchone()
        if row is None:
            return jsonify(error="article not found"), 404

        new_title = title if title is not None else row["title"]
        new_body = body if body is not None else row["body"]
        bumped = utcnow()
        db.execute(
            "UPDATE articles SET title = ?, body = ?, updated_at = ? WHERE id = ?",
            (new_title, new_body, bumped.isoformat(), article_id),
        )
        db.commit()

        row = db.execute(
            "SELECT * FROM articles WHERE id = ?", (article_id,)
        ).fetchone()
        return jsonify(row_to_dict(row)), 200

    @app.post("/articles")
    def create_article():
        payload = request.get_json(silent=True) or {}
        if not payload.get("title") or not payload.get("body"):
            return jsonify(error="'title' and 'body' are required"), 400
        db = _db()
        cur = db.execute(
            "INSERT INTO articles (title, body, updated_at) VALUES (?, ?, ?)",
            (payload["title"], payload["body"], utcnow().isoformat()),
        )
        db.commit()
        row = db.execute(
            "SELECT * FROM articles WHERE id = ?", (cur.lastrowid,)
        ).fetchone()
        return jsonify(row_to_dict(row)), 201


def make_app(db_path: str | None = None) -> Flask:
    application = create_app(db_path)
    register_routes(application)

    @application.teardown_appcontext
    def close_db(exc):
        db = g.pop("db", None)
        if db is not None:
            db.close()

    return application


if __name__ == "__main__":
    make_app().run(host="127.0.0.1", port=int(os.environ.get("PORT", "5000")))

