def utcnow() -> datetime:
    """Naive-UTC now, truncated to whole seconds.

    HTTP-dates (Last-Modified / If-Modified-Since) carry no sub-second
    precision, so updated_at is kept at second granularity.
    """
    return datetime.now(timezone.utc).replace(microsecond=0, tzinfo=None)


def bump(previous: datetime) -> datetime:
    """A timestamp guaranteed to be strictly later than ``previous``."""
    now = utcnow()
    return now if now > previous else previous + timedelta(seconds=1)
